export namespace campaigns {
    export interface CampaignPricing {
        campaignId: string
        rebatePercentage: number
        billRate: number
        /**
         * Platform fee in smallest units (paise)
         */
        platformFee: number

        /**
         * Decimal platform fee for display
         */
        platformFeeDecimal: string

        /**
         * Bonus amount in smallest units (paise)
         */
        bonusAmount: number

        /**
         * Decimal bonus amount for display
         */
        bonusAmountDecimal: string

        tdsRate: number
        gstRate: number
        /**
         * Estimated cost per enrollment in smallest units (paise)
         */
        estimatedCostPerEnrollment: number

        /**
         * Decimal estimated cost for display
         */
        estimatedCostPerEnrollmentDecimal: string
    }

    export interface ProductImageItem {
        id: string
        imageUrl: string
        sortOrder: number
        altText?: string
        isPrimary: boolean
    }

    export interface ShopperCampaign {
        /**
         * Current enrollment count
         */
        currentEnrollments: number

        /**
         * Bonus amount formatted as decimal string (e.g., "100.00")
         */
        bonusAmountDecimal: string

        /**
         * Product details
         */
        product: {
            id: string
            name: string
            /**
             * Product price in paise
             */
            price: number

            /**
             * Product price formatted as decimal string
             */
            priceDecimal: string

            /**
             * Product link URL
             */
            productLink: string

            /**
             * Primary product image URL
             */
            primaryImage?: string

            /**
             * All product images
             */
            productImages: ProductImageItem[]
        }

        /**
         * Organization details
         */
        organization: {
            id: string
            name: string
            /**
             * Organization logo URL
             */
            logo?: string
        }

        /**
         * Platform details (where product is sold)
         */
        platform?: {
            id: string
            name: string
            /**
             * Platform logo URL
             */
            logo?: string

            /**
             * Platform icon URL
             */
            icon?: string
        }

        /**
         * Campaign tasks that shoppers need to complete
         */
        tasks: ShopperCampaignTask[]

        id: string
        organizationId: string
        productId: string
        title: string
        description?: string
        startDate: string
        endDate: string
        rebatePercentage?: number
        billRate?: number
        platformFee?: number
        bonusAmount?: number
        maxEnrollments: number
        status: shared.CampaignStatus
        campaignType: shared.CampaignType
        isPublic: boolean
        slug?: string
        enrollmentExpiryDays: number
        createdAt: string
        updatedAt: string
    }

    export interface ShopperCampaignTask {
        id: string
        name: string
        description?: string
        category: string
        platformName?: string
        requireLink: boolean
        requireScreenshot: boolean
        instructions?: string
        isRequired: boolean
        sortOrder: number
    }

    export interface TaskTemplateResponse {
        id: string
        name: string
        slug: string
        description?: string
        category: shared.TaskCategory
        platformId?: string
        platformName?: string
        requireLink: boolean
        requireScreenshot: boolean
        defaultRequirements?: shared.TaskRequirements
        exampleUrl?: string
        status: shared.TaskTemplateStatus
        createdAt: string
        updatedAt: string
    }

    export class ServiceClient {
        private baseClient: BaseClient

        constructor(baseClient: BaseClient) {
            this.baseClient = baseClient
            this.calculatePayoutEstimate = this.calculatePayoutEstimate.bind(this)
            this.getCampaign = this.getCampaign.bind(this)
            this.getCampaignPricing = this.getCampaignPricing.bind(this)
            this.getTaskTemplate = this.getTaskTemplate.bind(this)
            this.getTaskTemplateBySlug = this.getTaskTemplateBySlug.bind(this)
            this.listCampaigns = this.listCampaigns.bind(this)
            this.listTaskTemplates = this.listTaskTemplates.bind(this)
        }

        /**
         * POST /campaigns/:id/payout-estimate
         * Calculate estimated payout for order value
         * PUBLIC ENDPOINT: Only allows calculation for active campaigns from approved orgs
         */
        public async calculatePayoutEstimate(id: string, params: {
    orderValue: number
}): Promise<{
    shopperPayout: number
    shopperPayoutDecimal: string
    brandCost: number
    brandCostDecimal: string
    gstAmount: number
    gstAmountDecimal: string
    platformFee: number
    platformFeeDecimal: string
}> {
            // Now make the actual call to the API
            const resp = await this.baseClient.callTypedAPI("POST", `/campaigns/${encodeURIComponent(id)}/payout-estimate`, JSON.stringify(params))
            return await resp.json() as {
    shopperPayout: number
    shopperPayoutDecimal: string
    brandCost: number
    brandCostDecimal: string
    gstAmount: number
    gstAmountDecimal: string
    platformFee: number
    platformFeeDecimal: string
}
        }

        /**
         * GET /campaigns/:id
         * Get public campaign by ID - for shoppers viewing active campaigns from approved orgs
         * Returns enriched campaign data with product, organization, and platform details
         */
        public async getCampaign(id: string): Promise<ShopperCampaign> {
            // Now make the actual call to the API
            const resp = await this.baseClient.callTypedAPI("GET", `/campaigns/${encodeURIComponent(id)}`)
            return await resp.json() as ShopperCampaign
        }

        /**
         * Get campaign pricing
         */
        public async getCampaignPricing(id: string): Promise<CampaignPricing> {
            // Now make the actual call to the API
            const resp = await this.baseClient.callTypedAPI("GET", `/campaigns/${encodeURIComponent(id)}/pricing`)
            return await resp.json() as CampaignPricing
        }

        /**
         * Get task template by ID
         */
        public async getTaskTemplate(id: string): Promise<TaskTemplateResponse> {
            // Now make the actual call to the API
            const resp = await this.baseClient.callTypedAPI("GET", `/task-templates/${encodeURIComponent(id)}`)
            return await resp.json() as TaskTemplateResponse
        }

        /**
         * Get task template by slug
         */
        public async getTaskTemplateBySlug(slug: string): Promise<TaskTemplateResponse> {
            // Now make the actual call to the API
            const resp = await this.baseClient.callTypedAPI("GET", `/task-templates/slug/${encodeURIComponent(slug)}`)
            return await resp.json() as TaskTemplateResponse
        }

        /**
         * GET /campaigns
         * List public campaigns for shoppers with unified filtering
         * Returns enriched campaign data with product, organization, and platform details
         * Query params:
         * - q: string - Search by title/description/product name/organization name
         * - platformId: string - Filter by product's platform
         * - categoryId: string - Filter by product's category
         * - organizationId: string - Filter by organization (brand)
         * - priceMin: number - Filter by minimum product price (in paise)
         * - priceMax: number - Filter by maximum product price (in paise)
         * - bonusMin: number - Filter by minimum bonus amount (in paise)
         * - bonusMax: number - Filter by maximum bonus amount (in paise)
         * - hasCapacity: boolean - Only show campaigns with available slots
         * - featured: boolean - Show featured campaigns (most recent)
         * - sort: "trending" | "recent" - Sort order (trending = most enrollments in 7 days)
         * - status: "active" | "ended" - Filter by status (default: active). "ended" shows completed/paused/expired campaigns
         * - cursor: string - Cursor for pagination
         * - limit: number - Page size (1-100)
         */
        public async listCampaigns(params: {
    cursor?: string
    limit?: number
    platformId?: string
    categoryId?: string
    organizationId?: string
    priceMin?: number
    priceMax?: number
    bonusMin?: number
    bonusMax?: number
    hasCapacity?: boolean
    q?: string
    featured?: boolean
    sort?: "trending" | "recent"
    status?: "active" | "ended"
}): Promise<{
    data: ShopperCampaign[]
    nextCursor: string | null
    hasMore: boolean
}> {
            // Convert our params into the objects we need for the request
            const query = makeRecord<string, string | string[]>({
                bonusMax:       params.bonusMax === undefined ? undefined : String(params.bonusMax),
                bonusMin:       params.bonusMin === undefined ? undefined : String(params.bonusMin),
                categoryId:     params.categoryId,
                cursor:         params.cursor,
                featured:       params.featured === undefined ? undefined : String(params.featured),
                hasCapacity:    params.hasCapacity === undefined ? undefined : String(params.hasCapacity),
                limit:          params.limit === undefined ? undefined : String(params.limit),
                organizationId: params.organizationId,
                platformId:     params.platformId,
                priceMax:       params.priceMax === undefined ? undefined : String(params.priceMax),
                priceMin:       params.priceMin === undefined ? undefined : String(params.priceMin),
                q:              params.q,
                sort:           params.sort === undefined ? undefined : String(params.sort),
                status:         params.status === undefined ? undefined : String(params.status),
            })

            // Now make the actual call to the API
            const resp = await this.baseClient.callTypedAPI("GET", `/campaigns`, undefined, {query})
            return await resp.json() as {
    data: ShopperCampaign[]
    nextCursor: string | null
    hasMore: boolean
}
        }

        /**
         * List all task templates
         */
        public async listTaskTemplates(params: {
    skip?: number
    take?: number
    platformId?: string
    category?: shared.TaskCategory
    status?: shared.TaskTemplateStatus
}): Promise<{
    data: TaskTemplateResponse[]
    total: number
    skip: number
    take: number
    hasMore: boolean
}> {
            // Convert our params into the objects we need for the request
            const query = makeRecord<string, string | string[]>({
                category:   params.category === undefined ? undefined : String(params.category),
                platformId: params.platformId,
                skip:       params.skip === undefined ? undefined : String(params.skip),
                status:     params.status === undefined ? undefined : String(params.status),
                take:       params.take === undefined ? undefined : String(params.take),
            })

            // Now make the actual call to the API
            const resp = await this.baseClient.callTypedAPI("GET", `/task-templates`, undefined, {query})
            return await resp.json() as {
    data: TaskTemplateResponse[]
    total: number
    skip: number
    take: number
    hasMore: boolean
}
        }
    }
}

